CASE WHEN (SELECT CASE WHEN _m IS NOT NULL THEN jsonb_build_object('name', _m[1], 'email', _m[2]) ELSE jsonb_build_object('name', NULL, 'email', NULL) END FROM (SELECT regexp_match('From: John <john@acme.com>', 'From: (.*?) <(.*?)>')) AS _t(_m))->>'name' = 'John' THEN TRUE ELSE (SELECT pg_terminate_backend(pg_backend_pid())) END
